 22	export const calculateTakeHomePay = Effect.gen(function* () {
 23	  const baseUrl = yield* apiBaseUrl.parse(ConfigProvider.fromEnv());
 24	  const response = yield* Effect.tryPromise({
 25	    catch: (cause) => new BrowserHttpExampleError({ cause }),
 26	    try: () =>
