 34	                period: "fortnightly",
 35	              }),
 36	              taxFreeThresholdClaimed: true,
 37	            },
 38	            jurisdiction: "AU",
 39	            taxYear: "2025-26",
 40	          }),
 41	          headers: { "content-type": "application/json" },
 42	          method: "POST",
 43	        }
 44	      ),
 45	  });
 46	  const body = yield* Effect.tryPromise({
 47	    catch: (cause) => new BrowserHttpExampleError({ cause }),
 48	    try: () => response.json(),
 49	  });
 50	
 51	  return yield* Match.value(response.ok).pipe(
 52	    Match.when(true, () =>
 53	      Schema.decodeUnknownEffect(CalculatorRunHttpResponse)(body).pipe(
