 10	const JsonValue = Schema.fromJsonString(Schema.Unknown);
 11	const StateStoreCredentialsJson = Schema.fromJsonString(
 12	  DocsDeploymentStateStoreCredentials
 13	);
 14	
 15	const decodeCredentials = (source: string) =>
 16	  Schema.decodeUnknownEffect(StateStoreCredentialsJson, {
 17	    onExcessProperty: "error",
 18	  })(source).pipe(Effect.option);
