 84	  credentials: DocsDeploymentStateStoreCredentials
 85	): Effect.Effect<
 86	  DocsDeploymentStateStoreCredentials,
 87	  DocsDeploymentInventoryInputError
 88	> =>
 89	  credentials.accountId === expectedAccountId
 90	    ? Effect.succeed(credentials)
 91	    : new DocsDeploymentInventoryInputError({
 92	        target: "cached state-store account identity",
 93	      });
