 16	};
 17	
 18	const runCredentialRead = (
 19	  fileSource: Option.Option<string>,
 20	  environmentSource: Option.Option<string>
 21	) =>
 22	  Effect.gen(function* credentialFixture() {
 23	    const fileSystem = yield* FileSystem.FileSystem;
 24	    const directory = yield* fileSystem.makeTempDirectoryScoped({
 25	      prefix: "taxkit-inventory-credentials-",
 26	    });
 27	    const path = `${directory}/cloudflare-state-store.json`;
 28	    yield* Option.match(fileSource, {
 29	      onNone: () => Effect.void,
 30	      onSome: (source) => fileSystem.writeFileString(path, source),
 31	    });
 32	    return yield* readDocsDeploymentStateStoreCredentials(
 33	      path,
 34	      environmentSource.pipe(Option.map(Redacted.make))
 35	    ).pipe(Effect.result);
 36	  }).pipe(Effect.scoped, Effect.provide(BunServices.layer), Effect.runPromise);
 37	
 38	describe("docs deployment state-store credential boundary", () => {
 39	  test("decodes the exact cached credential Schema and keeps the token redacted", async () => {
 40	    const result = await runCredentialRead(
 41	      Option.some(JSON.stringify(validCredentials)),
 42	      Option.none()
 43	    );
 44	    Result.match(result, {
 45	      onFailure: () => expect.unreachable(),
 46	      onSuccess: (credentials) => {
 47	        expect(credentials.accountId).toBe("account-123");
 48	        expect(credentials.url.hostname).toBe("state.example.test");
 49	        expect(String(credentials.authToken)).toBe("<redacted>");
 50	      },
 51	    });
 52	  });
 53	
 54	  test("uses a valid protected environment fallback when the cache is malformed", async () => {
 55	    const result = await runCredentialRead(
 56	      Option.some("{malformed"),
 57	      Option.some(JSON.stringify(validCredentials))
 58	    );
 59	    expect(Result.isSuccess(result)).toBe(true);
 60	  });
 61	
 62	  test("distinguishes absent credentials from malformed credentials", async () => {
 63	    const [absent, malformed] = await Promise.all([
 64	      runCredentialRead(Option.none(), Option.none()),
 65	      runCredentialRead(
 66	        Option.some(JSON.stringify({ accountId: "account-123" })),
