108	      onFailure: (error) =>
109	        Match.value(error).pipe(
110	          Match.tag("DocsDeploymentInventoryInputError", (failure) => {
111	            expect(JSON.stringify(failure)).not.toContain("secret-state-token");
112	            expect(failure.target).toBe(
