 20	export const readDocsDeploymentStateStoreCredentials = (
 21	  path: string,
 22	  environmentJson: Option.Option<Redacted.Redacted<string>>
 23	): Effect.Effect<
 24	  DocsDeploymentStateStoreCredentials,
 25	  DocsDeploymentInventoryInputError | DocsDeploymentInventoryReadError,
 26	  FileSystem.FileSystem
 27	> =>
 28	  Effect.gen(function* readStateStoreCredentialsAtBoundary() {
 29	    const fileSystem = yield* FileSystem.FileSystem;
 30	    const fileContents = yield* fileSystem.readFileString(path).pipe(
 31	      Effect.map(Option.some),
 32	      Effect.catchTag("PlatformError", (error) =>
 33	        Match.value(error.reason).pipe(
 34	          Match.when(
 35	            (reason) => reason._tag === "NotFound",
 36	            () => Effect.succeed(Option.none<string>())
 37	          ),
 38	          Match.orElse(
 39	            () =>
 40	              new DocsDeploymentInventoryReadError({
 41	                operation: "state-credentials-file",
 42	              })
 43	          )
 44	        )
 45	      )
 46	    );
 47	    const fileJsonObject = yield* Option.match(fileContents, {
 48	      onNone: () => Effect.succeed(false),
 49	      onSome: (source) =>
 50	        Schema.decodeUnknownEffect(JsonValue)(source).pipe(
 51	          Effect.map(Predicate.isObject),
 52	          Effect.catch(() => Effect.succeed(false))
 53	        ),
 54	    });
 55	    const fileCredentials = yield* Option.match(fileContents, {
 56	      onNone: () => Effect.succeed(Option.none()),
 57	      onSome: decodeCredentials,
 58	    });
 59	
 60	    if (Option.isSome(fileCredentials)) {
 61	      return fileCredentials.value;
 62	    }
 63	
 64	    const environmentCredentials = yield* Option.match(environmentJson, {
 65	      onNone: () => Effect.succeed(Option.none()),
 66	      onSome: (source) => decodeCredentials(Redacted.value(source)),
 67	    });
 68	    if (Option.isSome(environmentCredentials)) {
 69	      return environmentCredentials.value;
 70	    }
 71	
 72	    return yield* new DocsDeploymentInventoryInputError({
 73	      fileJsonObject,
 74	      fileVisible: Option.isSome(fileContents),
 75	      target:
 76	        Option.isSome(fileContents) || Option.isSome(environmentJson)
 77	          ? "invalid cached Cloudflare state-store credentials"
 78	          : "missing cached Cloudflare state-store credentials",
 79	    });
 80	  });
